class Solution {
    private int[][][] memo;
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        memo = new int[n][n][n];
        return dp(boxes, 0, n - 1, 0);
    }
    private int dp(int[] boxes, int l, int r, int k) {
        if (l > r) return 0;
        if (memo[l][r][k] != 0) return memo[l][r][k];
        int origL = l, origK = k;
        while (l + 1 <= r && boxes[l + 1] == boxes[l]) { l++; k++; }
        int res = (k + 1) * (k + 1) + dp(boxes, l + 1, r, 0);
        for (int m = l + 1; m <= r; m++) {
            if (boxes[m] == boxes[l]) {
                res = Math.max(res, dp(boxes, l + 1, m - 1, 0) + dp(boxes, m, r, k + 1));
            }
        }
        memo[origL][r][origK] = res;
        return res;
    }
}

class Solution {
    public int removeBoxes(int[] boxes) {
        int n = boxes.length;
        int[][][] dp = new int[n][n][n + 1];
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                dp[i][i][k] = (k + 1) * (k + 1);
            }
        }
        for (int len = 2; len <= n; len++) {
            for (int l = 0; l <= n - len; l++) {
                int r = l + len - 1;
                for (int k = 0; k < n; k++) {
                    int res = (k + 1) * (k + 1) + dp[l + 1][r][0];
                    for (int m = l + 1; m <= r; m++) {
                        if (boxes[m] == boxes[l]) {
                            int left = (l + 1 <= m - 1) ? dp[l + 1][m - 1][0] : 0;
                            res = Math.max(res, left + dp[m][r][k + 1]);
                        }
                    }
                    dp[l][r][k] = res;
                }
            }
        }
        return dp[0][n - 1][0];
    }
}
